const dz=document.getElementById("cc-drop");if(dz){["dragenter","dragover"].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.style.background="#eaf2fc"}));["dragleave","drop"].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.style.background=""}));dz.addEventListener("drop",e=>{if(e.dataTransfer.files.length)document.getElementById("cc-file").files=e.dataTransfer.files})}
